"""Administrator marketing campaign management page.

The page deliberately consumes only redacted campaign and aggregate contact
payloads. It never renders or accepts raw WhatsApp chat identifiers.
"""


def marketing_page():
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="color-scheme" content="light dark"><title>营销活动</title>
<style>
:root{font-family:Inter,system-ui,-apple-system,"Microsoft YaHei",sans-serif;color:#172033;background:#f5f7fb}
body{margin:0;padding:28px}.page{max-width:1180px;margin:auto}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:22px}.eyebrow{font-size:12px;color:#67728b;letter-spacing:.08em}.top h1{margin:5px 0;font-size:28px}.top p{margin:0;color:#667087}.grid{display:grid;grid-template-columns:360px minmax(0,1fr);gap:18px}.card{background:#fff;border:1px solid #e4e8f1;border-radius:18px;padding:20px;box-shadow:0 12px 35px #1e2c4b0b;margin-bottom:18px}.form-grid{display:grid;gap:12px}.field{display:grid;gap:6px}.field label{font-size:12px;color:#69748b}.field input,.field textarea,.field select{width:100%;box-sizing:border-box;border:1px solid #d8deea;border-radius:10px;padding:10px;font:inherit;background:#fff;color:#172033}.field textarea{min-height:80px;resize:vertical}.check{display:flex!important;align-items:center;gap:8px}.check input{width:18px;height:18px}.actions{display:flex;gap:8px;align-items:center;margin-top:14px;flex-wrap:wrap}.button{border:0;border-radius:10px;padding:10px 15px;background:#365eea;color:#fff;font-weight:700;cursor:pointer}.button.secondary{background:#edf1fb;color:#33405d}.button.danger{background:#fbe9eb;color:#b4293b}.notice{font-size:13px;color:#5c6984}.notice.error{color:#b4293b}.campaigns{display:grid;gap:10px}.campaign{padding:14px;border:1px solid #e5e9f0;border-radius:14px;background:#fff}.campaign-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.campaign h3{margin:0;font-size:16px}.campaign p{margin:5px 0;color:#667087;font-size:13px}.pill{font-size:11px;padding:4px 8px;border-radius:99px;background:#eaf8ef;color:#247747;white-space:nowrap}.pill.off{background:#f2f3f5;color:#70798b}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:12px}.metric{padding:9px;border-radius:10px;background:#f5f7fb}.metric b{display:block;font-size:18px;color:#25304c}.metric span{font-size:11px;color:#6b758a}.campaign-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}.campaign-actions button{border:1px solid #d8deea;border-radius:8px;background:#f7f9fd;color:#40506f;padding:6px 8px;cursor:pointer;font-size:11px}.privacy-note{padding:12px;border-radius:12px;background:#fff5df;color:#8a5c00;font-size:12px;line-height:1.6}.empty{padding:24px;text-align:center;color:#7a8497;border:1px dashed #d8deea}@media(max-width:900px){body{padding:15px}.grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style></head><body><main class="page">
<header class="top"><div><div class="eyebrow">AI SALES WORKSPACE</div><h1>营销活动</h1><p>配置可暂停、可恢复的主动沟通流程；客户标识只在服务端使用哈希，页面只展示阶段和统计。</p></div><a class="button secondary" href="/">返回工作台</a></header>
<div class="grid"><section class="card"><h2 id="formTitle">新建活动</h2><form id="campaignForm"><div class="form-grid"><div class="field"><label for="campaignId">活动编号</label><input id="campaignId" maxlength="80" pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,79}" required></div><div class="field"><label for="campaignName">活动名称</label><input id="campaignName" maxlength="200" required></div><div class="field"><label for="objective">活动目标</label><textarea id="objective" maxlength="4000" required></textarea></div><div class="field"><label for="targetRules">目标规则 JSON</label><textarea id="targetRules">{"idle_days":7}</textarea></div><div class="field"><label for="productScope">产品范围（逗号分隔）</label><input id="productScope" placeholder="g5-plus"></div><div class="field"><label for="cadence">节奏 JSON</label><textarea id="cadence">{"first_delay_hours":0,"follow_up_hours":24}</textarea></div><div class="field"><label for="maxTouches">最大触达次数</label><input id="maxTouches" type="number" min="1" max="100" value="1" required></div><div class="field"><label for="quietHours">安静时段 JSON</label><textarea id="quietHours">{}</textarea></div><label class="check"><input id="allowImageSend" type="checkbox">允许营销图片</label></div><div class="actions"><button class="button" type="submit">保存活动</button><button class="button secondary" id="resetForm" type="button">清空</button><span id="formNotice" class="notice" role="status"></span></div></form><p class="privacy-note" data-policy="product_image_global_kill_switch">活动目标规则不能包含客户号码、chat_id、customer_id 或其他原始客户标识。图片发送仍受全局停止开关、产品范围和营销图片开关约束。</p></section>
<section class="card"><div class="top"><div><h2>活动列表</h2><p class="notice">仅展示活动配置、阶段计数和发送状态；联系人明细不含原始客户 ID。</p></div><button id="refresh" class="button secondary" type="button">刷新</button></div><div id="campaigns" class="campaigns"><div class="empty">正在读取活动…</div></div></section></div>
</main><script>
(()=>{'use strict';
const $=id=>document.getElementById(id);let csrf='';let editing='';
async function ensureCsrf(){if(csrf)return csrf;const r=await fetch('/api/security/csrf',{credentials:'same-origin',cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.message||'安全校验不可用');csrf=d.csrf_token||'';return csrf;}
async function api(url,options={}){const headers=new Headers(options.headers||{});if(options.method&&options.method!=='GET'){headers.set('X-CSRF-Token',await ensureCsrf());}const r=await fetch(url,{...options,headers,credentials:'same-origin',cache:'no-store'});const type=r.headers.get('content-type')||'';const d=type.includes('application/json')?await r.json():await r.text();if(!r.ok)throw Error(d.message||'请求失败');return d;}
function jsonValue(id,fallback){try{return JSON.parse($(id).value||fallback);}catch(_){throw Error($(id).previousElementSibling?.textContent+' JSON 格式无效');}}
function metric(label,value){const e=document.createElement('div');e.className='metric';const b=document.createElement('b');b.textContent=String(value??0);const s=document.createElement('span');s.textContent=label;e.append(b,s);return e;}
function render(items){const root=$('campaigns');root.replaceChildren();if(!items||!items.length){const e=document.createElement('div');e.className='empty';e.textContent='暂无活动';root.append(e);return;}items.forEach(item=>{const row=document.createElement('article');row.className='campaign';const head=document.createElement('div');head.className='campaign-head';const title=document.createElement('h3');title.textContent=item.name||item.campaign_id;const pill=document.createElement('span');pill.className='pill'+(item.active?'':' off');pill.textContent=item.active?'运行中':'已暂停';head.append(title,pill);row.append(head);const copy=document.createElement('p');copy.textContent=item.objective||'';row.append(copy);const stats=item.stats||{};const metrics=document.createElement('div');metrics.className='metrics';metrics.append(metric('联系人',stats.contacts_total),metric('已触达',stats.sent),metric('图片发送',stats.image_sent),metric('客户回复',stats.customer_replies));row.append(metrics);const actions=document.createElement('div');actions.className='campaign-actions';const edit=document.createElement('button');edit.type='button';edit.textContent='编辑';edit.addEventListener('click',()=>fill(item));const contacts=document.createElement('button');contacts.type='button';contacts.textContent='联系人统计';contacts.addEventListener('click',()=>loadContacts(item.campaign_id));const toggle=document.createElement('button');toggle.type='button';toggle.textContent=item.active?'暂停':'恢复';toggle.addEventListener('click',()=>toggleCampaign(item));actions.append(edit,contacts,toggle);row.append(actions);root.append(row);});}
function fill(item){editing=item.campaign_id; $('formTitle').textContent='编辑活动';$('campaignId').value=item.campaign_id||'';$('campaignId').disabled=true;$('campaignName').value=item.name||'';$('objective').value=item.objective||'';$('targetRules').value=JSON.stringify(item.target_rules||{},null,2);$('productScope').value=(item.product_scope||[]).join(',');$('cadence').value=JSON.stringify(item.cadence||{},null,2);$('maxTouches').value=String(item.max_touches||1);$('quietHours').value=JSON.stringify(item.quiet_hours||{},null,2);$('allowImageSend').checked=Boolean(item.allow_image_send);}
function clearForm(){editing='';$('formTitle').textContent='新建活动';$('campaignForm').reset?.();$('campaignId').disabled=false;$('targetRules').value='{"idle_days":7}';$('cadence').value='{"first_delay_hours":0,"follow_up_hours":24}';$('quietHours').value='{}';$('formNotice').textContent='';}
async function save(event){event.preventDefault();$('formNotice').textContent='保存中…';try{const body={campaign_id:$('campaignId').value.trim(),name:$('campaignName').value.trim(),objective:$('objective').value.trim(),target_rules:jsonValue('targetRules','{}'),product_scope:$('productScope').value.split(',').map(v=>v.trim()).filter(Boolean),cadence:jsonValue('cadence','{}'),max_touches:Number($('maxTouches').value),quiet_hours:jsonValue('quietHours','{}'),allow_image_send:$('allowImageSend').checked};const result=await api(editing?('/api/marketing/campaigns/'+encodeURIComponent(editing)):'/api/marketing/campaigns',{method:editing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('formNotice').textContent='已保存';fill(result);await load();}catch(error){$('formNotice').textContent=error.message;$('formNotice').classList.add('error');}}
async function toggleCampaign(item){try{await api('/api/marketing/campaigns/'+encodeURIComponent(item.campaign_id)+'/'+(item.active?'pause':'resume'),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reason:'管理员操作'})});await load();}catch(error){$('formNotice').textContent=error.message;$('formNotice').classList.add('error');}}
async function loadContacts(campaignId){try{const data=await api('/api/marketing/campaigns/'+encodeURIComponent(campaignId)+'/contacts');const stats=data.stats||{};const summary=Object.entries(stats.contacts_by_stage||{}).map(([key,value])=>key+': '+value).join(' · ')||'暂无联系人';$('formNotice').className='notice';$('formNotice').textContent='联系人阶段：'+summary;}catch(error){$('formNotice').textContent=error.message;$('formNotice').classList.add('error');}}
async function load(){try{const data=await api('/api/marketing/campaigns?include_inactive=1');render(data.items||[]);}catch(error){$('campaigns').textContent=error.message;}}
$('campaignForm').addEventListener('submit',save);$('resetForm').addEventListener('click',clearForm);$('refresh').addEventListener('click',load);clearForm();load();
})();</script></body></html>'''


__all__ = ["marketing_page"]
